use polars_error::{PolarsError, PolarsResult};
use arrow::datatypes::ArrowDataType;
use arrow::array::Array;
use simd_json::BorrowedValue;

fn safe_deserialize(json_str: &str, dtype: ArrowDataType, allow_extra: bool) -> PolarsResult<Box<dyn Array>> {
    let value = simd_json::from_str(json_str).map_err(|e| {
        PolarsError::ComputeError(format!("Failed to parse JSON: {}", e))
    })?;

    let array = match dtype {
        ArrowDataType::Int64 => {
            let array = value.as_array().ok_or_else(|| {
                PolarsError::ComputeError("Expected array type for Int64".to_string())
            })?;
            polars_core::prelude::Int64Array::try_from(array.as_slice())
                .map_err(|e| PolarsError::ComputeError(e.to_string()))?
                .into_boxed()
        }
        ArrowDataType::UInt64 => {
            let array = value.as_array().ok_or_else(|| {
                PolarsError::ComputeError("Expected array type for UInt64".to_string())
            })?;
            polars_core::prelude::UInt64Array::try_from(array.as_slice())
                .map_err(|e| PolarsError::ComputeError(e.to_string()))?
                .into_boxed()
        }
        ArrowDataType::Float64 => {
            let array = value.as_array().ok_or_else(|| {
                PolarsError::ComputeError("Expected array type for Float64".to_string())
            })?;
            polars_core::prelude::Float64Array::try_from(array.as_slice())
                .map_err(|e| PolarsError::ComputeError(e.to_string()))?
                .into_boxed()
        }
        ArrowDataType::Utf8 => {
            let array = value.as_array().ok_or_else(|| {
                PolarsError::ComputeError("Expected array type for Utf8".to_string())
            })?;
            polars_core::prelude::Utf8Array::<i32>::try_from(array.as_slice())
                .map_err(|e| PolarsError::ComputeError(e.to_string()))?
                .into_boxed()
        }
        _ => {
            return Err(PolarsError::ComputeError(format!(
                "Unsupported data type: {}",
                dtype
            )));
        }
    };

    Ok(array)
}

use arrow::array::{Array, StructArray};
use polars_error::{PolarsError, PolarsResult};
use polars_json::json::{deserialize, infer};
use simd_json::to_borrowed_value;

fn deserialize_json_object_to_struct(json_str: &str, allow_extra: bool) -> PolarsResult<StructArray> {
    let value = to_borrowed_value(json_str).map_err(|e| PolarsError::from(e))?;
    let schema = infer(&value).map_err(|e| PolarsError::from(e))?;
    let array = deserialize(&value, &schema, allow_extra).map_err(|e| PolarsError::from(e))?;
    Ok(array)
}

fn list_cached_packages<TSys>(sys: &TSys, cache_root: &Path) -> Result<Vec<String>, std::io::Error>
where
    TSys: FsReadDir,
{
    let mut package_names = Vec::new();
    let mut dir = sys.read_dir(cache_root)?;

    while let Some(entry) = dir.next() {
        let entry = entry?;
        let path = entry.path();
        if path.is_dir() {
            if let Some(name) = path.file_name() {
                if let Some(name_str) = name.to_str() {
                    package_names.push(name_str.to_string());
                }
            }
        }
    }

    Ok(package_names)
}

