fn create_custom_module_file(root: &Path, filename: OsString, output: PathBuf) -> Result<(), anyhow::Error> {
    let mut content = String::new();

    // Traverse the tree to collect module names
    collect_module_names(root, &mut content);

    // Write the collected content to the specified file
    fs_err::write(output, content)?;

    Ok(())
}

fn collect_module_names(root: &Path, content: &mut String) {
    if let Some(tree) = Tree::from_path(root) {
        for item in tree.items() {
            if let Some(name) = item.name() {
                if name != "mod.rs" && name != "lib.rs" {
                    content.push_str(&format!("pub mod {};\n", name));
                }
            }
        }
    }
}

use std::io::{Read, Write};
use lzf::{self, LzfError, LzfResult};

fn compress_stream<R: Read, W: Write>(reader: &mut R, writer: &mut W) -> LzfResult<()> {
    const BUFFER_SIZE: usize = 8192;
    let mut buffer = [0u8; BUFFER_SIZE];
    let mut compressed_buffer = Vec::new();

    loop {
        let bytes_read = reader.read(&mut buffer)?;
        if bytes_read == 0 {
            break;
        }

        // Compress the buffer
        let compressed = lzf::compress(&buffer[..bytes_read], &mut compressed_buffer)?;
        let length = compressed.len() as u64;

        // Write the length as a 4-byte little-endian prefix
        writer.write_all(&length.to_le_bytes())?;
        writer.write_all(&compressed)?;
    }

    Ok(())
}

use polars_core::prelude::*;
use polars_testing::asserts::{assert_series_equal, SeriesEqualOptions};

fn assert_dataframe_ignore_columns(
    left: &DataFrame,
    right: &DataFrame,
    ignore_columns: &[&str],
) -> PolarsResult<()> {
    // Check if both DataFrames have the same number of rows
    if left.height() != right.height() {
        return Err(PolarsError::ComputeError("DataFrames have different row counts".into()));
    }

    // Check if both DataFrames have the same columns (excluding ignored ones)
    let left_cols: Vec<&str> = left.columns().iter().filter(|col| !ignore_columns.contains(col)).map(|s| s.as_str()).collect();
    let right_cols: Vec<&str> = right.columns().iter().filter(|col| !ignore_columns.contains(col)).map(|s| s.as_str()).collect();

    if left_cols != right_cols {
        return Err(PolarsError::ComputeError("DataFrames have different column sets (excluding ignored columns)".into()));
    }

    // Compare each column that is not in the ignore list
    for col in left_cols {
        let left_series = left.column(col).unwrap();
        let right_series = right.column(col).unwrap();

        assert_series_equal(
            left_series,
            right_series,
            SeriesEqualOptions::default(),
        )?;
    }

    Ok(())
}

fn bi_pipe_echo(message: &[u8]) -> Result<Vec<u8>, std::io::Error> {
    let (mut read_pipe, mut write_pipe) = bi_pipe_pair_raw();

    // Spawn a task to read from the read_pipe and write back to the write_pipe
    let read_handle = tokio::spawn(async move {
        let mut buffer = vec![];
        let _ = read_pipe.read_buf(&mut buffer).await;
        buffer
    });

    // Write the message to the write_pipe
    let _ = write_pipe.write_all(message).await;

    // Wait for the read task to complete and get the echoed message
    let echoed_message = read_handle.await.unwrap();

    Ok(echoed_message)
}

