use cli::anonymous_fd;
use tempfile::NamedTempFile;
use anyhow::Result;
use std::io::Read;

fn copy_anonymous_fd_to_temp(fd_path: &str) -> Result<std::path::PathBuf> {
    // Open the anonymous file descriptor
    let fd = anonymous_fd::open(fd_path)?;

    // Create a temporary file
    let mut temp_file = NamedTempFile::new()?;
    let temp_path = temp_file.path().to_path_buf();

    // Read from the anonymous FD and write to the temporary file
    let mut buffer = [0; 1024];
    loop {
        let n = fd.read(&mut buffer)?;
        if n == 0 {
            break;
        }
        temp_file.write_all(&buffer[..n])?;
    }

    // Sync the temporary file to ensure data is written
    temp_file.sync_all()?;

    Ok(temp_path)
}

