use multibase;
use ssi_multicodec::MultiEncodedBuf;
use ssi_dids_core::resolution::Error;

fn validate_did_key_format(did_str: &str) -> Result<(), Error> {
    if !did_str.starts_with("did:key:") {
        return Err(Error::InvalidFormat);
    }

    let did_key_part = &did_str["did:key:".len()..];
    if did_key_part.is_empty() {
        return Err(Error::InvalidFormat);
    }

    let mut decoder = multibase::Decoder::new(did_key_part.as_bytes());
    let mut payload = Vec::new();
    let mut result = Ok(());

    while let Some(byte) = decoder.next() {
        payload.push(byte);
    }

    if decoder.error().is_some() {
        result = Err(Error::InvalidMultibase);
    } else if payload.is_empty() {
        result = Err(Error::InvalidPayload);
    } else {
        let multi_encoded = MultiEncodedBuf::from(payload);
        if let Err(e) = multi_encoded {
            result = Err(Error::InvalidMulticodec);
        }
    }

    result
}

use ckb_types::packed::{Byte32, MerkleProof};
use ckb_types::utilities::CBMT;
use ckb_types::prelude::*;

fn generate_tx_merkle_proof(
    tx_hashes: &[Byte32],
    indices: &[u32]
) -> Result<MerkleProof, String> {
    if tx_hashes.is_empty() || indices.is_empty() {
        return Err("Transaction hashes and indices must not be empty".to_string());
    }

    if tx_hashes.len() != indices.len() {
        return Err("Transaction hashes and indices must have the same length".to_string());
    }

    let mut cbmt = CBMT::new();
    for (i, &hash) in tx_hashes.iter().enumerate() {
        cbmt.add_leaf(hash, i as u64);
    }

    let mut proof = MerkleProof::new();
    for &index in indices {
        if index >= cbmt.leaf_count() {
            return Err(format!("Index {} is out of bounds", index));
        }
        let path = cbmt.get_path(index);
        proof.set_path(path);
    }

    Ok(proof)
}

