use contrafact::{lambda, Lambda, Target};

pub fn range_between<O, T, FStart, FEnd, C>(label: impl ToString, start: FStart, end: FEnd, cmp: C) -> Lambda<'static, O, O>
where
    O: Target<'static> + Clone,
    T: Target<'static> + PartialOrd + Clone,
    FStart: Fn(&O) -> T + Clone + Send + Sync,
    FEnd: Fn(&O) -> T + Clone + Send + Sync,
    C: Fn(&T, &T) -> bool + Clone + Send + Sync,
{
    lambda("range_between", (), move |g, (), mut o: O| {
        let s = start(&o);
        let e = end(&o);
        if !cmp(&s, &e) {
            g.fail(format!("range constraint failed: start {:?} end {:?}", s, e))?;
        }
        Ok(o)
    })
}

fn batch_retrieve(&self, start: BlockNumber, end: BlockNumber) -> Result<Vec<Vec<u8>>, Error> {
    let mut result = Vec::new();
    let mut current = start;

    // Lock the freezer to avoid concurrent access
    let guard = self.lock().map_err(|e| e.into())?;

    while current <= end {
        let block_data = guard.get_block(current).ok_or(Error::BlockNotFound)?;
        result.push(block_data.to_vec());
        current += 1;
    }

    Ok(result)
}

fn validate_and_generate_block_proof<F>(
    &self,
    peer: PeerIndex,
    nc: &dyn CKBProtocolContext,
    last_block: &core::BlockView,
    block_hashes: Vec<packed::Byte32>,
    custom_validator: F,
) -> Status
where
    F: Fn(&core::BlockView) -> bool + Send + Sync,
{
    let mut valid_hashes: Vec<packed::Byte32> = Vec::new();
    let mut valid_indices: Vec<usize> = Vec::new();

    for (index, hash) in block_hashes.iter().enumerate() {
        if let Some(block) = nc.get_block_by_hash(*hash) {
            if custom_validator(&block) {
                valid_hashes.push(*hash);
                valid_indices.push(index);
            }
        }
    }

    let proof = self.reply_proof(peer, nc, last_block, &valid_hashes);
    proof
}

fn merge_tables(storage_src: &ParquetStorage, src_table: &str, storage_dst: &mut ParquetStorage, dst_table: &str) -> Result<(), Error> {
    // Read all rows from the source table
    let src_rows = storage_src.read_table(src_table)?;

    // Read existing rows from the destination table
    let dst_rows = storage_dst.read_table(dst_table)?;

    // Combine rows from both tables
    let mut merged_rows = dst_rows;
    merged_rows.extend(src_rows);

    // Write the merged rows back to the destination table
    storage_dst.write_table(dst_table, merged_rows)?;

    Ok(())
}

