fn set_default_shell(workflow: &mut Workflow, shell: &str) {
    if let Some(defaults) = &mut workflow.defaults {
        if defaults.run.is_none() {
            defaults.run = Some(RunDefaults {
                shell: Some(shell.to_string()),
                ..Default::default()
            });
        }
    } else {
        workflow.defaults = Some(Defaults {
            run: Some(RunDefaults {
                shell: Some(shell.to_string()),
                ..Default::default()
            }),
            ..Default::default()
        });
    }

    for job in &mut workflow.jobs {
        if job.run.is_none() {
            job.run = Some(RunDefaults {
                shell: Some(shell.to_string()),
                ..Default::default()
            });
        }
    }
}

fn insert_rows_with_schema_check(
    storage: &mut ParquetStorage,
    table_name: &str,
    rows: Vec<DataRow>,
    expected_schema: &Schema,
) -> Result<(), Error> {
    let metadata = storage.metadata()?;
    let table_exists = metadata.contains_table(table_name)?;

    if !table_exists {
        storage.create_table(table_name, expected_schema)?;
        return Ok(());
    }

    let existing_schema = metadata.get_table_schema(table_name)?;
    if existing_schema != expected_schema {
        return Err(Error::SchemaMismatch {
            expected: expected_schema.to_string(),
            actual: existing_schema.to_string(),
        });
    }

    for row in rows {
        if row.schema() != expected_schema {
            return Err(Error::SchemaMismatch {
                expected: expected_schema.to_string(),
                actual: row.schema().to_string(),
            });
        }
    }

    storage.insert_rows(table_name, rows)?;
    Ok(())
}

