use std::fs::File;
use std::io::{BufReader, Seek, SeekFrom, BufRead};
use std::num::NonZeroUsize;
use polars::prelude::*;
use polars_error::PolarsResult;
use polars_json::ndjson::{infer_iter, deserialize_iter};

fn ndjson_path_to_dataframe(path: &std::path::Path, infer_rows: usize) -> PolarsResult<DataFrame> {
    if infer_rows == 0 {
        return Err(PolarsError::ComputeError("infer_rows must be greater than 0".into()));
    }

    let infer_rows = NonZeroUsize::new(infer_rows).ok_or(PolarsError::ComputeError("infer_rows must be greater than 0".into()))?;

    let file = File::open(path)?;
    let mut reader = BufReader::new(file);

    let mut buffer = Vec::new();
    let mut line_count = 0;

    // Read the first N lines to infer schema
    while line_count < infer_rows {
        let mut line = String::new();
        let bytes_read = reader.read_line(&mut line)?;
        if bytes_read == 0 {
            return Err(PolarsError::ComputeError("Unexpected end of file while inferring schema".into()));
        }
        buffer.push(line.clone());
        line_count += 1;
    }

    // Seek back to the start of the file
    reader.seek(SeekFrom::Start(0))?;

    // Infer schema from the first N lines
    let schema = infer_iter(buffer.iter().map(|s| s.as_str()))?;

    // Deserialize the entire file using the inferred schema
    let df = deserialize_iter(reader, &schema)?;

    Ok(df)
}

fn set_http_encoding(mut server_fn: ServerFnCall, encoding: &str) -> Result<ServerFnCall, syn::Error> {
