}

fn build_custom_emoji_table(emoji_list: &[&str]) -> ([u8; 256], [usize; 256]) {
    let mut emoji_table = [0u8; 256];
    let mut index_table = [0usize; 256];

    for (i, &emoji) in emoji_list.iter().enumerate() {
        if i >= 256 {
            break;
        }
        let mut hash = 0;
        for c in emoji.chars() {
            hash = hash.wrapping_add(c as u32);
            hash = hash.wrapping_mul(37);
        }
        let idx = hash as u8 % 256;
        emoji_table[idx as usize] = i as u8;
        index_table[idx as usize] = i;
    }

    (emoji_table, index_table)
}

