fn generate_validation_report(
    part_results: Vec<(u64, bool)>,
    total_required_parts: u64,
) -> String {
    let mut success_count = 0;
    let mut failed_parts = Vec::new();

    for (part_id, is_success) in part_results {
        if !is_success {
            failed_parts.push(part_id);
        } else {
            success_count += 1;
        }
    }

    let success_rate = if total_required_parts > 0 {
        (success_count as f64 / total_required_parts as f64) * 100.0
    } else {
        0.0
    };

    let success_rate_formatted = format!("{:.2}%", success_rate);
    let failed_parts_str = if failed_parts.is_empty() {
        "None".to_string()
    } else {
        format!("Failed parts: {:?}", failed_parts)
    };

    format!(
        "Validation Report:\nTotal required parts: {}\nSuccess count: {}\nSuccess rate: {}\n{}",
        total_required_parts,
        success_count,
        success_rate_formatted,
        failed_parts_str
    )
}

use rustpython_parser_vendored::source_location::LineIndex;
use rustpython_parser_vendored::source_location::OneIndexed;
use rustpython_parser_vendored::text_size::TextSize;

fn offset_from_line_column(text: &str, line: OneIndexed, column: OneIndexed) -> Option<TextSize> {
    let line_index = LineIndex::from(text);
    let line_start = line_index.start_of_line(line);
    let line_end = line_index.end_of_line(line);
    let line_text = &text[line_start..line_end];

    if column > OneIndexed::new(line_text.len() as u32) {
        return None;
    }

    let column_offset = if column == OneIndexed::new(1) {
        line_start
    } else {
        let mut offset = line_start;
        let mut remaining = column - OneIndexed::new(1);
        let mut i = 0;
        while remaining > OneIndexed::new(0) && i < line_text.len() {
            offset += line_text[i] as TextSize;
            if i < line_text.len() - 1 && line_text[i] != b'\n' {
                remaining -= OneIndexed::new(1);
            }
            i += 1;
        }
        offset
    };

    Some(column_offset)
}

fn generate_document_with_keys(jwks: Vec<JWK>) -> Result<Document, GenerateError> {
    if jwks.is_empty() {
        return Err(GenerateError::EmptyInput);
    }

    let did_key = DIDKey::from_jwk(&jwks[0])?;
    let did = did_key.did();

    let mut verification_methods = Vec::new();
    let mut verification_method_counter = 0;

    for jwk in &jwks {
        let method_type = VerificationMethodType::Multikey;
        let method_id = format!("did:key:{}", did);
        let verification_method = VerificationMethod::new(
            method_id,
            method_type,
            jwk,
            None,
        );
        verification_methods.push(verification_method);
        verification_method_counter += 1;
    }

    let mut document = Document::new(did);
    for method in verification_methods {
        document.add_verification_method(method)?;
    }

    Ok(document)
}

fn connect_with_auth(url: &str, token: &str, api_key: &str) -> Result<(Sender<Compat<EitherStream>>, Receiver<Compat<EitherStream>>), WsHandshakeError> {
    let url = Url::parse(url).map_err(|e| WsHandshakeError::InvalidUrl(e.to_string()))?;
    let mut headers = http::HeaderMap::new();
    headers.insert("Authorization", format!("Bearer {}", token).parse().unwrap());
    headers.insert("X-API-Key", api_key.parse().unwrap());
    let transport = WsTransportClientBuilder::new()
        .url(url)
        .headers(headers)
        .timeout(Duration::from_secs(10))
        .build()?;
    let (sender, receiver) = transport.connect()?;
    Ok((Sender::new(Compat::new(sender)), Receiver::new(Compat::new(receiver))))
}

