#[derive(Error, Debug)]
pub enum GenerateError {
    #[error("Failed to generate new key pair")]
    KeyGenerationError,
    #[error("Failed to create new DID")]
    DIDCreationError,
    #[error("Failed to create new verification method")]
    VerificationMethodCreationError,
    #[error("Failed to construct DID document")]
    DocumentConstructionError,
}

fn generate_new_key_pair() -> Result<(JWK, DIDBuf), GenerateError> {
    let did_key = DIDKey::generate();
    let did = did_key.did();
    let jwk = did_key.jwk();
    Ok((jwk, did))
}

fn create_verification_method(
    did: &DIDBuf,
    key: &JWK,
    method_type: VerificationMethodType,
) -> Result<VerificationMethod, GenerateError> {
    let did_url = DIDURLBuf::new(did, "key-1")?;
    let key_id = did_url.to_string();
    let public_key = PublicKey::from_jwk(key)?;
    Ok(VerificationMethod {
        id: key_id,
        type_: method_type,
        public_key: ValueOrReference::Value(public_key),
        ..Default::default()
    })
}

fn create_did_document(
    old_did: &DIDBuf,
    old_verification_method: &VerificationMethod,
    new_verification_method: &VerificationMethod,
) -> Result<Document, GenerateError> {
    let mut methods = HashMap::new();
    methods.insert(old_verification_method.id.clone(), old_verification_method.clone());
    methods.insert(new_verification_method.id.clone(), new_verification_method.clone());
    Ok(Document {
        did: old_did.clone(),
        verification_method: methods,
        ..Default::default()
    })
}

fn rotate_did_key(old_jwk: &JWK) -> Result<Document, GenerateError> {
    // Generate new key pair
    let (new_jwk, new_did) = generate_new_key_pair()?;

    // Create old verification method
    let old_method = create_verification_method(old_did, old_jwk, VerificationMethodType::Ed25519)?;

    // Create new verification method
    let new_method = create_verification_method(&new_did, &new_jwk, VerificationMethodType::Ed25519)?;

    // Create updated DID document
    let document = create_did_document(&new_did, &old_method, &new_method)?;

    Ok(document)
}

