use crate::state::{Service, DidSolError};
use itertools::Itertools;

fn merge_services(
    existing: Vec<Service>,
    incoming: Vec<Service>,
    allow_overwrites: bool,
) -> Result<Vec<Service>, DidSolError> {
    let mut merged = existing.clone();
    let mut seen = std::collections::HashSet::new();

    for service in incoming {
        let key = service.id.clone();
        if seen.contains(&key) {
            return Err(DidSolError::DuplicateServiceId(key));
        }
        seen.insert(key.clone());

        if let Some(index) = merged.iter().position(|s| s.id == key) {
            if allow_overwrites {
                merged[index] = service;
            } else {
                return Err(DidSolError::DuplicateServiceId(key));
            }
        } else {
            merged.push(service);
        }
    }

    Ok(merged)
}

