use petgraph::Graph;

fn list_all_transitive_dependencies(
    workspace_root: &Path,
) -> Result<Vec<BuildpackId>, BuildBuildpackDependencyGraphError> {
    let dependency_graph = build_libcnb_buildpacks_dependency_graph(workspace_root)?;
    let mut all_dependencies = Vec::new();
    let root_node = DependencyNode::new(BuildpackId::from("root_buildpack"));

    // Traverse the graph to collect all transitive dependencies
    let mut visited = std::collections::HashSet::new();
    let mut stack = vec![root_node];

    while let Some(node) = stack.pop() {
        if visited.contains(&node.id) {
            continue;
        }
        visited.insert(node.id.clone());
        all_dependencies.push(node.id.clone());
        for dependency in get_dependencies(&dependency_graph, &node.id) {
            stack.push(DependencyNode::new(dependency));
        }
    }

    Ok(all_dependencies)
}

