}

use crate::field::baby_bear::Elem;

fn batch_invert(elems: &[Elem]) -> Vec<Elem> {
    if elems.is_empty() {
        return Vec::new();
    }

    let n = elems.len();
    let mut inv = vec![Elem::zero(); n];
    inv[0] = elems[0].inverse();

    for i in 1..n {
        inv[i] = inv[i - 1] * elems[i];
    }

    for i in (0..n).rev() {
        inv[i] = inv[i] * inv[i];
    }

    inv
}

fn stream_ndjson_tostructs<R: BufRead>(mut reader: R, allow_extra: bool) -> PolarsResult<Vec<StructArray>> {
    let mut structs = Vec::new();
    let mut file_reader = FileReader::new(reader);

    for result in file_reader {
        let line = match result {
            Ok(line) => line,
            Err(e) => return Err(PolarsError::from(e)),
        };

        let value = match to_borrowed_value(&line) {
            Ok(val) => val,
            Err(e) => return Err(PolarsError::from(e)),
        };

        let schema = infer(&value, allow_extra).map_err(|e| PolarsError::from(e))?;
        let array = deserialize(&value, &schema, allow_extra).map_err(|e| PolarsError::from(e))?;

        structs.push(array);
    }

    Ok(structs)
}

use std::path::{Path, PathBuf};
