fn get_block_hashes_in_range(
    shared: &ckb_shared::Shared,
    start: ckb_types::core::BlockNumber,
    end: ckb_types::core::BlockNumber,
) -> Result<Vec<ckb_types::packed::Byte32>, String> {
    if start > end {
        return Err("Start block number must be less than or equal to end block number".to_string());
    }

    let mut hashes = Vec::new();
    let mut current = start;

    while current <= end {
        if let Some(hash) = shared.get_block_hash(current) {
            hashes.push(hash);
            if hashes.len() >= GET_BLOCKS_PROOF_LIMIT {
                return Err("Block hash retrieval exceeded the protocol limit".to_string());
            }
        } else {
            return Err("Failed to retrieve block hash".to_string());
        }
        current += 1;
    }

    Ok(hashes)
}

