        return false;
    }
    true
}

fn generate_leverage_neutral_cf(
    cf_jump: impl Fn(&Complex<f64>) -> Complex<f64> + Clone,
    cf_diffusion: impl Fn(&Complex<f64>) -> Complex<f64> + Clone,
    r0: f64,
    r1: f64,
    k0: f64,
    k1: f64,
    v0: f64,
    sigma0: f64,
    sigma1: f64,
    rho: f64,
    eta0: f64,
    eta1: f64,
    t: f64,
    num_steps: usize,
) -> impl Fn(&Complex<f64>) -> Complex<f64> {
    let dt = t / num_steps as f64;

    let mut jump_factor = Complex::new(1.0, 0.0);
    let mut diffusion_factor = Complex::new(1.0, 0.0);

    for _ in 0..num_steps {
        let jump = cf_jump(&jump_factor);
        let diffusion = cf_diffusion(&diffusion_factor);

        let r = r0 + r1 * dt;
        let k = k0 + k1 * dt;
        let v = v0 + v1 * dt;
        let sigma = sigma0 + sigma1 * dt;
        let rho = rho;
        let eta = eta0 + eta1 * dt;

        let jump_factor = jump * Complex::new(r, k);
        let diffusion_factor = diffusion * Complex::new(v, sigma);
    }

    move |z: &Complex<f64>| {
        let r = r0 + r1 * t;
        let k = k0 + k1 * t;
        let v = v0 + v1 * t;
        let sigma = sigma0 + sigma1 * t;
        let rho = rho;
        let eta = eta0 + eta1 * t;

        let jump = cf_jump(&Complex::new(r, k));
        let diffusion = cf_diffusion(&Complex::new(v, sigma));

        let mut result = Complex::new(1.0, 0.0);
        for _ in 0..num_steps {
            let jump = cf_jump(&Complex::new(r, k));
            let diffusion = cf_diffusion(&Complex::new(v, sigma));

            let z_term = z * Complex::new(rho, eta);
            let z_term = z_term * Complex::new(1.0, 0.0);
            let z_term = z_term * Complex::new(1.0, 0.0);

            result = result * jump * diffusion;
        }

        result
    }
}

fn apply_patch_with_context(patch: &Patch<'_>, old: &str) -> Result<String, (u64, String)> {
    let mut result = String::new();
    let mut lines = old.lines().enumerate().collect::<Vec<_>>();
    let mut line_index = 0;

    for (i, patch_line) in patch.lines.iter().enumerate() {
        if let Some(line) = lines.get(line_index) {
            let line_number = line.0 as u64 + 1;
            let line_content = line.1;

            match patch_line {
                Line::Original(original) => {
                    if line_index < lines.len() && line_content == original {
                        result.push_str(line_content);
                        result.push('\n');
                        line_index += 1;
                    } else {
                        return Err((line_number, format!("Original line mismatch at line {}", line_number)));
                    }
                }
                Line::Modified(modified) => {
                    if line_index < lines.len() {
                        result.push_str(modified);
                        result.push('\n');
                        line_index += 1;
                    } else {
                        return Err((line_number, format!("Patch line out of bounds at line {}", line_number)));
                    }
                }
                Line::Context(context) => {
                    if line_index < lines.len() && line_content == context {
                        result.push_str(line_content);
                        result.push('\n');
                        line_index += 1;
                    } else {
                        return Err((line_number, format!("Context line mismatch at line {}", line_number)));
                    }
                }
            }
        } else {
            return Err((line_number, format!("Patch line out of bounds at line {}", line_number)));
        }
    }

    Ok(result)
}

