use web_time::Duration;
use crate::{Run, RunParams, RunDuration};

fn find_fastest_run(runs: &[Run]) -> Option<usize> {
    runs.iter().enumerate().fold(None, |min_index, (index, &run)| {
        let total_duration = run.upload_duration + run.download_duration;
        match min_index {
            None => Some(*index),
            Some(min_index) => {
                let min_total = runs[min_index].upload_duration + runs[min_index].download_duration;
                if total_duration < min_total {
                    Some(*index)
                } else {
                    Some(min_index)
                }
            }
        }
    })
}

use netlink_proto::{new_connection, sys::SocketAddr};
use netlink_packet_audit::AuditMessage;
use netlink_packet_core::NetlinkPayload;
use futures::StreamExt;
use netlink_sys::protocols::NETLINK_AUDIT;
use tokio::io::{AsyncRead, AsyncWrite};
use tokio::net::UnixStream;
use std::path::Path;

fn run_with_handler<F, Fut>(handler: F) -> Result<(), String>
where
    F: Fn(AuditMessage) -> Fut + Send + Sync + 'static,
    Fut: std::future::Future<Output = ()> + Send,
{
    let socket_path = Path::new("/var/run/audit.sock");
    let socket_addr = SocketAddr::new_unix(socket_path);

    let (mut rx, _) = new_connection(NETLINK_AUDIT, socket_addr).map_err(|e| e.to_string())?;

    tokio::spawn(async move {
        while let Some(payload) = rx.next().await {
            if let Ok(AuditMessage::AuditMessage(msg)) = payload.parse() {
                let handler_fut = handler(msg);
                tokio::spawn(async move {
                    if let Err(e) = handler_fut.await {
                        eprintln!("Error in handler: {}", e);
                    }
                });
            }
        }
    });

    Ok(())
}

fn batch_send_messages(state: Rc<RefCell<OpState>>, rid: ResourceId, messages: Vec<&[u8]>) -> Result<(), WebsocketError> {
    let state = state.borrow();
    let ws = state.websocket_resources.get(&rid).ok_or(WebsocketError::ResourceNotFound)?;
    let ws = ws.downcast_ref::<ServerWebSocket>().ok_or(WebsocketError::ResourceInvalid)?;

    let mut lock = ws.write_lock();
    let mut frame = Frame::new();
    let mut buffer = Vec::new();

    for message in messages {
        buffer.clear();
        buffer.extend_from_slice(message);
        frame.set_data(buffer);
        frame.set_opcode(OpCode::Text);
        frame.set_final(false);
        frame.set_mask(false);

        if let Err(e) = ws.write_frame(&frame) {
            return Err(e);
        }

        // Check for backpressure
        if ws.is_backpressured() {
            return Ok(());
        }

        frame.set_final(true);
    }

    Ok(())
}

use risc0_core::field::baby_bear::{Elem, ExtElem};

fn ext_elem_to_bytes(e: ExtElem) -> [u8; 16] {
    let mut bytes = [0u8; 16];
    let mut offset = 0;

    for elem in e.0 {
        let mut byte_array = [0u8; 4];
        for i in 0..4 {
            byte_array[i] = (elem.0 >> (8 * (3 - i))) as u8;
        }
        bytes[offset..offset + 4].copy_from_slice(&byte_array);
        offset += 4;
    }

    bytes
}

use anyhow::Result;
use std::collections::HashMap;
use std::sync::{Arc, Mutex};
use std::thread;
use std::vec::Vec;

fn validate_multiple_shards(
    chain_id: &str,
    epoch_id: EpochId,
    epoch_height: u64,
    shard_ids: &[ShardId],
    state_roots: &HashMap<ShardId, StateRoot>,
    external: &ExternalConnection,
) -> Result<HashMap<ShardId, bool>> {
    let result_map = Arc::new(Mutex::new(HashMap::new()));
    let mut handles = vec![];

    for &shard_id in shard_ids {
        let state_root = state_roots.get(&shard_id).ok_or_else(|| anyhow!("State root not found for shard {}", shard_id))?;
        let result_map_clone = Arc::clone(&result_map);
        let external_clone = external.clone();
        let chain_id_clone = chain_id.to_string();
        let epoch_id_clone = epoch_id;
        let epoch_height_clone = epoch_height;

        let handle = thread::spawn(move || {
            let result = validate_epoch_shard(
                &chain_id_clone,
                epoch_id_clone,
                epoch_height_clone,
                shard_id,
                state_root,
                external_clone,
            );
            let mut result_map = result_map_clone.lock().unwrap();
            result_map.insert(shard_id, result.is_ok());
        });

        handles.push(handle);
    }

    for handle in handles {
        handle.join().ok();
    }

    Ok(Arc::try_unwrap(result_map)
        .expect("All threads should have finished")
        .into_inner()
        .unwrap())
}

use crate::{NpmCache, NpmCacheSys, WithFolderSyncLockError};
use std::time::Duration;
use sys_traits::{FsReadDir, FsMetadata, FsRemoveDirAll};

fn clean_stale_cache_entries<TSys: NpmCacheSys>(
    cache: &NpmCache<TSys>,
    max_age: Duration,
) -> Result<(), WithFolderSyncLockError> {
    let cache_dir = cache.path();
    let mut entries = vec![];

    // Read all entries in the cache directory
    for entry in cache_dir.read_dir()? {
        let entry = entry?;
        let path = entry.path();
        if path.is_dir() {
            entries.push(path);
        }
    }

    // Process each entry to check if it's stale
    for path in entries {
        let metadata = path.metadata()?;
        let last_accessed = metadata.accessed()?;
        let time_since_access = chrono::Duration::seconds((chrono::Utc::now() - last_accessed).num_seconds());

        if time_since_access > max_age {
            // Remove the stale directory
            path.remove_dir_all()?;
        }
    }

    Ok(())
}

use json_diff_ng::{Mismatch, PathElement};
use serde_json::Value;

fn apply_mismatch(original: &Value, mismatch: &Mismatch) -> Value {
    let mut result = original.clone();
    apply_mismatch_recursive(&mut result, mismatch, &mut Vec::new())
}

fn apply_mismatch_recursive(value: &mut Value, mismatch: &Mismatch, path: &mut Vec<PathElement>) -> bool {
    if let Some(path_elements) = &mismatch.path {
        let mut current = value;
        let mut path_elements = path_elements.clone();
        let mut matched = false;

        while let Some(element) = path_elements.pop() {
            match element {
                PathElement::Index(index) => {
                    if let Some(arr) = current.as_array_mut() {
                        if index < arr.len() {
                            current = &mut arr[index];
                            matched = true;
                        } else {
                            return false;
                        }
                    } else {
                        return false;
                    }
                }
                PathElement::Key(key) => {
                    if let Some(obj) = current.as_object_mut() {
                        if let Some(val) = obj.get_mut(&key) {
                            current = val;
                            matched = true;
                        } else {
                            return false;
                        }
                    } else {
                        return false;
                    }
                }
            }
        }

        if matched {
            *current = mismatch.right.clone();
            return true;
        }
    }

    false
}

use anyhow::{Context, Result};
use borsh::BorshDeserialize;
use near_primitives::state_part::PartId;
