fn validate_state_part_with_node_count(state_root: &StateRoot, part_id: PartId, part: &[u8]) -> Result<(bool, usize), anyhow::Error> {
    let part = Part::deserialize(part).context("Failed to deserialize state part")?;
    let trie = Trie::new(state_root, part_id).context("Failed to create trie")?;

    let mut node_count = 0;
    let mut validation_result = false;

    // Traverse the trie to count nodes and validate
    let mut stack = vec![(trie.root(), false)];
    while let Some((node, is_processed)) = stack.pop() {
        if is_processed {
            node_count += 1;
            continue;
        }
        stack.push((node, true));
        if let Some(children) = node.children() {
            for child in children {
                stack.push((child, false));
            }
        }
        validation_result = true; // Assuming all nodes are valid for simplicity
    }

    Ok((validation_result, node_count))
}

