use celestia_rpc::prelude::*;
use tokio::time::{sleep, Duration};

fn get_blobs_with_retry<C>(
    client: &C,
    height: u64,
    namespace: Namespace,
) -> Result<Vec<Blob>, Box<dyn std::error::Error>>
where
    C: BlobClient + Sync,
{
    let mut retries = 3;
    let mut delay = Duration::from_secs(1);

    loop {
        match client.get_blobs(height, namespace) {
            Ok(blobs) => {
                return Ok(blobs);
            }
            Err(e) => {
                if retries == 0 {
                    return Err(e.into());
                }
                retries -= 1;
                sleep(delay).await;
                delay *= 2;
            }
        }
    }
}

